// =====================================================
// Constants & Config
// =====================================================

#define PI      3.14159265359
#define TWO_PI  6.28318530718

#define BASE_STEP   0.04
#define GRAD_EPS    0.04
#define MAX_STEPS   160
#define SPEC_POWER  50.0
#define SPEC_COLOR  vec3(1.2, 1.0, 0.8)

#define FIXED_UP    vec3(0.0, 1.0, 0.0)
#define TAN_HFOVY   0.5773502691896257

#define RES iResolution
#define MS  iMouse 

// =====================================================
// Helpers
// =====================================================

float rand(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453);
}

vec3 camRay(vec3 forward, vec2 uv) {
    vec3 right = normalize(cross(forward, FIXED_UP));
    vec3 up    = cross(right, forward);
    return normalize(TAN_HFOVY * (uv.x * (RES.x / RES.y) * right + uv.y * up) + forward);
}

// renamed from outerProduct to avoid conflicts
mat3 opMatrix(vec3 n) {
    return mat3(
        n.x*n.x, n.x*n.y, n.x*n.z,
        n.y*n.x, n.y*n.y, n.y*n.z,
        n.z*n.x, n.z*n.y, n.z*n.z
    );
}

mat3 rotation(vec3 axis, float angle) {
    float c = cos(angle), s = sin(angle);
    vec3 n = normalize(axis);
    return (1.0 - c) * opMatrix(n) +
           mat3(c, s*n.z, -s*n.y,
               -s*n.z, c, s*n.x,
                s*n.y, -s*n.x, c);
}

// =====================================================
// Time-varying vivid colormap
// =====================================================

vec3 vividColormap(float t, float timeShift) {
    // rainbow spread across R-G-B cycle, animated by time
    vec3 base = 0.5 + 0.5 * cos(TWO_PI * (t + timeShift + vec3(0.0, 0.33, 0.67)));

    // boost saturation/contrast
    base = pow(base, vec3(0.8));

    // extra modulation: density-dependent hue shift
    float hueShift = sin((t + timeShift) * 6.283) * 0.25;
    vec3 mod = 0.5 + 0.5 * cos(TWO_PI * (t + timeShift + hueShift + vec3(0.0, 0.2, 0.4)));

    return mix(base, mod, 0.5);
}

// =====================================================
// Volume Definition
// =====================================================

vec3 hopf(vec3 p) {
    float psq = dot(p, p);
    vec4 q = vec4(2.0*p, psq - 1.0) / (psq + 1.0);
    return vec3(
        2.0 * (q.y*q.z - q.x*q.w),
        1.0 - 2.0 * (q.y*q.y + q.w*q.w),
        2.0 * (q.x*q.y + q.z*q.w)
    );
}

vec4 sampleVolume(vec3 p, mat3 m, float phase) {
    vec3 rp = m * hopf(p);

    float theta = atan(-rp.z, rp.x);
    float sdy   = pow(0.5 + 0.5*cos(rp.y * 5.0 * PI), 2.0);
    float sdt   = 0.5 + 0.5*sin(theta * 20.0);

    float d1 = max(sdt * sdy, 0.55 * sdy);
    d1 = mix(d1, 0.8 * sdy, phase);

    return vec4(0.5 + 0.5 * rp.y, 0.0, 0.0, d1);
}

// =====================================================
// Shading
// =====================================================

vec4 shadePoint(vec3 p, vec3 camPos, mat3 m, float phase, vec3 lightPos, float timeShift) {
    vec4 density = sampleVolume(p, m, phase);
    if (density.a < 0.35) return vec4(0.0);

    // Approximate gradient
    vec3 grad = vec3(
        sampleVolume(p + vec3(GRAD_EPS,0,0), m, phase).a - sampleVolume(p - vec3(GRAD_EPS,0,0), m, phase).a,
        sampleVolume(p + vec3(0,GRAD_EPS,0), m, phase).a - sampleVolume(p - vec3(0,GRAD_EPS,0), m, phase).a,
        sampleVolume(p + vec3(0,0,GRAD_EPS), m, phase).a - sampleVolume(p - vec3(0,0,GRAD_EPS), m, phase).a
    );
    vec3 normal = normalize(-grad);

    // Use vivid colormap with time evolution
    vec3 matColor = vividColormap(density.r, timeShift);

    // Blend with surface orientation for extra color depth
    matColor = mix(matColor, 0.6 + 0.6 * normal, 0.25);

    // Emissive tint adds purple/green pops
    matColor += 0.2 * vec3(0.6, 0.3, 0.8) * pow(density.a, 2.0);

    // Lighting
    vec3 L = normalize(lightPos - p);
    vec3 V = normalize(camPos - p);
    vec3 H = normalize(L + V);

    float diff = max(dot(normal, L), 0.0);
    vec3 diffuse  = diff * matColor;
    vec3 specular = pow(max(dot(normal, H), 0.0), SPEC_POWER) * SPEC_COLOR;

    vec3 color = 0.35 * matColor + 0.55 * (diffuse + specular);
    float alpha = pow(density.a, 2.5);

    return vec4(color, alpha);
}

// =====================================================
// Raymarch
// =====================================================

void raymarch(vec3 ro, vec3 rd, out vec4 accum, float phase, mat3 m, vec3 lightPos, float timeShift) {
    accum = vec4(0.0);
    vec2 tRange = vec2(mix(1.0, 2.75, phase), 6.0);

    float t = tRange.x;
    float stepSize = BASE_STEP;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec4 cHit = shadePoint(ro + t * rd, ro, m, phase, lightPos, timeShift);

        // adaptive stepping
        if (cHit.a > 0.01) stepSize = BASE_STEP * 0.6;
        else stepSize = BASE_STEP * 1.5;

        vec4 contrib = vec4(cHit.rgb, 1.0) * (stepSize / 0.08 * cHit.a);
        accum += (1.0 - accum.a) * contrib;

        if (t > tRange.y || accum.a > 0.985) return;
        t += stepSize;
    }
}

// =====================================================
// Main
// =====================================================

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / RES.xy;

    float phase = smoothstep(0.2, 0.8, MS.z > 0.0 ? MS.y / RES.y : 0.5 + 0.5*cos(0.4*iTime));
    float angle = MS.z > 0.0 ? TWO_PI * MS.x / RES.x : PI + 1.5 * iTime;

    // time-based palette shift (cycles every ~20 seconds)
    float timeShift = iTime * 0.05;

    vec3 camPos = vec3(0.0, 1.0, 3.5);
    vec3 rd = camRay(normalize(-camPos), uv * 2.0 - 1.0);
    mat3 m = rotation(normalize(vec3(1.0, sin(iTime), 1.0)), -angle);

    vec3 lightPos = camPos + vec3(0.0, 1.2, 0.0);

    vec4 objColor;
    raymarch(camPos + rand(fragCoord) * rd * BASE_STEP, rd, objColor, phase, m, lightPos, timeShift);

    vec3 finalColor = objColor.rgb + (1.0 - objColor.a) * vec3(0.15, 0.2, 0.25);
    fragColor = vec4(finalColor, 1.0);
}
